<main class="container py-5"><div class="dashboard-head"><div><span class="eyebrow">ADMINISTRATION</span><h1 class="fw-bold">Équipe</h1></div><a href="/admin" class="btn btn-outline-dark">Dashboard</a></div><form method="post" action="/admin/equipe/create" class="form-card row g-3 mb-5"><input type="hidden" name="csrf" value="<?=csrf()?>"><h3 class="h5 fw-bold">Créer un compte coach</h3><div class="col-md-3"><input name="firstname" class="form-control" placeholder="Prénom" required></div><div class="col-md-3"><input name="lastname" class="form-control" placeholder="Nom" required></div><div class="col-md-3"><input type="email" name="email" class="form-control" placeholder="E-mail" required></div><div class="col-md-3"><input type="password" name="password" minlength="8" class="form-control" placeholder="Mot de passe" required></div><div class="col-md-4"><input name="phone" class="form-control" placeholder="Téléphone"></div><div class="col-md-4"><input name="city" class="form-control" placeholder="Ville"></div><div class="col-md-4"><button class="btn btn-accent w-100">Créer le coach</button></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>État</th><th></th></tr></thead><tbody><?php foreach($staff as $x): ?><tr><td><?=e($x['firstname'].' '.$x['lastname'])?></td><td><?=e($x['email'])?></td><td><?=e($x['role'])?></td><td><?=$x['active']?'Actif':'Inactif'?></td><td><?php if($x['role']==='coach'): ?><form method="post" action="/admin/equipe/toggle"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn btn-sm btn-outline-secondary">Activer/Désactiver</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></main>